choose.when:
AND b."公開範囲コード" = 'FAMILY'


        AND b."所有家族学生ID" = #{familyStudentId}


        AND 1 = 0

choose.otherwise:
AND (b."公開範囲コード" = 'GLOBAL'

    OR b."所有家族学生ID" = #{familyStudentId}

    )

mapper.select:
SELECT ,



 ORDER BY b."置頂フラグ" DESC, b."最終読書日時" DESC NULLS LAST, b."書籍ID" DESC
 LIMIT #{limit} OFFSET #{offset}

mapper.delete:
DELETE FROM public."RED_自分の本棚情報"
 WHERE "アカウントID" = #{accountId}
   AND "書籍ID" = #{bookId}

mapper.select:
SELECT EXISTS (SELECT 1 FROM public."RED_自分の本棚情報" s
                WHERE s."アカウントID" = #{accountId}
                  AND s."書籍ID" = #{bookId})
